Here is the commit message:
drm: fix error found in some cases after the patch
 d1af5cd86997

The patch d1af5cd86997 ("drm: get rid of DRM_DEBUG_* log
calls in drm core, files drm_a*.c") fails when the drm_device
cannot be found in the parameter plane_state->crtc.
Fix it using plane_state->plane.

Reported-by: kernel test robot <oliver.sang@intel.com>
Fixes: 6e22dc358377 ("drm: get rid of DRM_DEBUG_* log calls in drm core, files drm_a*.c")
Signed-off-by: Claudio Suarez <cssk@net-c.es>
[danvet: fix Fixes: line]
Signed-off-by: Daniel Vetter <daniel.vetter@ffwll.ch>
Link: https://patchwork.freedesktop.org/patch/msgid/YaiXEARd8z2C463h@gineta.localdomain
(cherry picked from commit 521d459b1935628a7caa0753429f880dae2dbfc9)
Signed-off-by: Thomas Zimmermann <tzimmermann@suse.de>

Here is the root cause:
The bug was caused by the removal of DRM_DEBUG_* log calls in the previous patch, which led to situations where the logging attempted to access `plane_state->crtc->dev` when the `drm_device` could not be found in the `crtc`. This resulted in incorrect logging behavior and potential errors when trying to update the plane state of a disabled CRTC. The fix involved changing the logging to reference `plane_state->plane->dev` instead, ensuring that the correct device context is used.

Here is the patch:
  */
 int drm_atomic_helper_check_plane_state(struct drm_plane_state *plane_state,
 					const struct drm_crtc_state *crtc_state,
 					int min_scale,
 					int max_scale,
 					bool can_position,
 					bool can_update_disabled)
 {
 	struct drm_framebuffer *fb = plane_state->fb;
 	struct drm_rect *src = &plane_state->src;
 	struct drm_rect *dst = &plane_state->dst;
 	unsigned int rotation = plane_state->rotation;
 	struct drm_rect clip = {};
 	int hscale, vscale;

 	WARN_ON(plane_state->crtc && plane_state->crtc != crtc_state->crtc);

 	*src = drm_plane_state_src(plane_state);
 	*dst = drm_plane_state_dest(plane_state);

 	if (!fb) {
 		plane_state->visible = false;
 		return 0;
 	}

 	/* crtc should only be NULL when disabling (i.e., !fb) */
 	if (WARN_ON(!plane_state->crtc)) {
 		plane_state->visible = false;
 		return 0;
 	}

 	if (!crtc_state->enable && !can_update_disabled) {
-		drm_dbg_kms(plane_state->crtc->dev,
-			       "Cannot update plane of a disabled CRTC.\n");
+		drm_dbg_kms(plane_state->plane->dev,
+			    "Cannot update plane of a disabled CRTC.\n");
 		return -EINVAL;
 	}

 	drm_rect_rotate(src, fb->width << 16, fb->height << 16, rotation);

 	/* Check scaling */
 	hscale = drm_rect_calc_hscale(src, dst, min_scale, max_scale);
 	vscale = drm_rect_calc_vscale(src, dst, min_scale, max_scale);
 	if (hscale < 0 || vscale < 0) {
-		drm_dbg_kms(plane_state->crtc->dev,
-			       "Invalid scaling of plane\n");
+		drm_dbg_kms(plane_state->plane->dev,
+			    "Invalid scaling of plane\n");
 		drm_rect_debug_print("src: ", &plane_state->src, true);
 		drm_rect_debug_print("dst: ", &plane_state->dst, false);
 		return -ERANGE;
 	}

 	if (crtc_state->enable)
 		drm_mode_get_hv_timing(&crtc_state->mode, &clip.x2, &clip.y2);

 	plane_state->visible = drm_rect_clip_scaled(src, dst, &clip);

 	drm_rect_rotate_inv(src, fb->width << 16, fb->height << 16, rotation);

 	if (!plane_state->visible)
 		/*
 		 * Plane isn't visible; some drivers can handle this
 		 * so we just return success here.  Drivers that can't
 		 * (including those that use the primary plane helper's
 		 * update function) will return an error from their
 		 * update_plane handler.
 		 */
 		return 0;

 	if (!can_position && !drm_rect_equals(dst, &clip)) {
-		drm_dbg_kms(plane_state->crtc->dev,
-			       "Plane must cover entire CRTC\n");
+		drm_dbg_kms(plane_state->plane->dev,
+			    "Plane must cover entire CRTC\n");
 		drm_rect_debug_print("dst: ", dst, false);
 		drm_rect_debug_print("clip: ", &clip, false);
 		return -EINVAL;
 	}

 	return 0;
 }
 EXPORT_SYMBOL(drm_atomic_helper_check_plane_state);


